/**
 * The pot's figure mid-spin: the first `locked` digits are the real ones and every later digit
 * is a blur face picked by hashing `seed` with its position (a leading one never zero), so the
 * spin is the same every replay. Separators stay put, so the width never jumps.
 */
export function crapsPotReelFace(copy, locked, seed = 0) {
  let digit = 0;
  return [...String(copy)].map((char) => {
    if (char < '0' || char > '9') return char;
    const index = digit++;
    if (index < locked) return char;
    let hash = Math.imul((seed + 1) ^ Math.imul(index + 1, 0x9e3779b1), 0x85ebca6b);
    hash = Math.imul(hash ^ (hash >>> 13), 0xc2b2ae35) ^ (hash >>> 16);
    const face = (hash >>> 0) % (index === 0 ? 9 : 10);
    return String(index === 0 ? face + 1 : face);
  }).join('');
}
